-- Phase 031 WS-C — Full Syria locations dataset (governorates -> cities -> areas).
--
-- DATA SOURCE / ATTRIBUTION:
--   Syrian Arab Republic - Subnational Administrative Boundaries (COD-AB).
--   OCHA Field Information Services Section (FISS), via HDX:
--     https://data.humdata.org/dataset/cod-ab-syr
--   License: CC BY-IGO (attribution required). Bilingual (ar+en) names and
--   per-feature representative centroids ship with the dataset.
--   Marquee city neighborhoods are a small curated supplement.
--   Generated by tool/locations/build_syria_seed.mjs
--   Source used for this build: OCHA HDX COD-AB v02 (cached).
--
-- MAPPING: ADM1 -> existing governorate (referenced by key, NOT re-inserted);
--          ADM2 (districts/manatiq) -> public.cities;
--          ADM3 (sub-districts) + curated neighborhoods -> public.areas.
--          Every city gets a default "<city>-center" area so submit_listing
--          always has at least one selectable area.
--
-- ROW COUNTS (new rows; ON CONFLICT DO NOTHING makes this idempotent):
--   new cities: 62
--   new areas:  372
--
-- All new rows: is_system=false (cities), is_active=true. Centroids validated
-- inside lat 32..37 / lng 35..43 (areas_centroid_syria_bounds).

BEGIN;

-- ============================================================
-- CITIES (62 rows) — ADM2 districts/manatiq
-- ============================================================
