SELECT g.id, 'azaz', '{"ar":"اعزاز","en":"A''zaz"}'::jsonb, 10, true, false
FROM public.governorates g WHERE g.key = 'aleppo'
ON CONFLICT (governorate_id, key) DO NOTHING;

