-- ============================================================
-- AREAS (372 rows) — ADM3 sub-districts + curated neighborhoods
-- city_id resolved by joining governorates + cities on (gov key, city key).
-- ============================================================
INSERT INTO public.areas (city_id, key, display_name, position, is_active, centroid_lat, centroid_lng)
SELECT c.id, 'azaz-center', '{"ar":"وسط اعزاز","en":"A''zaz Center"}'::jsonb, 10, true, 36.466819, 37.208013
FROM public.cities c JOIN public.governorates g ON g.id = c.governorate_id
WHERE g.key = 'aleppo' AND c.key = 'azaz'
ON CONFLICT (city_id, key) DO NOTHING;

INSERT INTO public.areas (city_id, key, display_name, position, is_active, centroid_lat, centroid_lng)
SELECT c.id, 'albu-kamal-center', '{"ar":"وسط البوكمال","en":"Abu Kamal Center"}'::jsonb, 10, true, 34.588078, 40.694134
FROM public.cities c JOIN public.governorates g ON g.id = c.governorate_id
WHERE g.key = 'deir-ez-zor' AND c.key = 'albu-kamal'
ON CONFLICT (city_id, key) DO NOTHING;

